values (1, 'باسم الغيث', '9647886443032', '07886443032', 'info@bassemalghaith.com', 'بغداد، العراق', 'السبت – الخميس: 10 صباحاً – 10 مساءً', 'باسم الغيث وجهتك للأجهزة المنزلية الأصلية في العراق. نختار لك أفضل الماركات العالمية بضمان حقيقي، ونوصل طلبك إلى باب بيتك في جميع المحافظات، مع خدمة ما بعد البيع تليق بثقتك.', 10000, 500000, true, true, false, 'مصرف الرافدين – باسم الغيث – رقم الحساب: يُرسل عبر الواتساب بعد تأكيد الطلب', 'https://instagram.com/', 'https://facebook.com/', 'https://tiktok.com/')
