insert into public.products (slug, name, brand_id, category_id, sku, model_number, short_description, description, price, old_price, stock, images, video_url, video_poster, video_orientation, specs, features, colors, warranty, is_featured, is_new, is_bestseller, sales_count, created_at)
select v.slug, v.name, b.id, c.id, v.sku, v.model, v.short_d, v.descr, v.price, v.old_price, v.stock, v.images, v.video_url, v.video_poster, v.orient, v.specs::jsonb, v.features, v.colors::jsonb, v.warranty, v.featured, v.is_new, v.best, v.sales, now() - (v.age || ' days')::interval
from (values
('french-door-fridge-22','ثلاجة فرنسية 4 أبواب 22 قدم','samsung','refrigerators','BG-RF-1001','RF22A4220SR','تبريد ثلاثي مستقل وموزع ماء وثلج','ثلاجة فرنسية فاخرة بأربعة أبواب وسعة 22 قدم، بنظام تبريد ثلاثي مستقل يحافظ على رطوبة الخضار وطزاجة اللحوم، مع موزع ماء وثلج خارجي وضاغط إنفرتر رقمي هادئ وموفر للطاقة.',1850000,2150000,8,array['/images/products/french-door-fridge.webp'],null,null,'horizontal','[{"label":"السعة","value":"22 قدم (623 لتر)"},{"label":"نوع الضاغط","value":"إنفرتر رقمي"},{"label":"تصنيف الطاقة","value":"A+"},{"label":"الأبعاد","value":"91 × 178 × 72 سم"},{"label":"موزع الماء","value":"نعم، مع صانعة ثلج"}]',array['تبريد ثلاثي مستقل','موزع ماء وثلج','ضاغط إنفرتر بضمان 10 سنوات','إضاءة LED داخلية'],'[{"name":"فضي","hex":"#C4C7CC"},{"name":"أسود","hex":"#24282D"}]','ضمان سنتين شامل + 10 سنوات على الضاغط',true,false,true,64,40),
('bottom-freezer-black-18','ثلاجة بفريزر سفلي 18 قدم – أسود مطفي','lg','refrigerators','BG-RF-1002','GBB72MCDFN','تصميم أسود مطفي وتقنية Door Cooling','ثلاجة بتصميم أوروبي أنيق وفريزر سفلي واسع، مع تقنية التبريد من الباب لتوزيع هواء بارد متساوٍ وتقنية No Frost بدون تكوّن ثلج.',1150000,null,5,array['/images/products/black-fridge.webp'],null,null,'horizontal','[{"label":"السعة","value":"18 قدم (510 لتر)"},{"label":"نوع الضاغط","value":"إنفرتر خطي"},{"label":"تصنيف الطاقة","value":"A++"},{"label":"الأبعاد","value":"60 × 203 × 68 سم"}]',array['No Frost','Door Cooling','تشغيل هادئ 36 ديسبل'],'[{"name":"أسود مطفي","hex":"#1E2125"}]','ضمان سنتين + 10 سنوات على الضاغط',false,true,false,12,6),
('front-load-washer-9kg','غسالة أمامية 9 كغم بالبخار','lg','washers','BG-WM-2001','F4V5VYP0W','بخار يقضي على 99.9% من الجراثيم','غسالة أمامية بتقنية الذكاء الاصطناعي التي تتعرف على نوع القماش وتختار الحركة المناسبة، مع دورة بخار للتعقيم ومحرك دفع مباشر بضمان 10 سنوات.',925000,1050000,14,array['/images/products/front-load-washer.webp'],null,null,'horizontal','[{"label":"سعة الغسيل","value":"9 كغم"},{"label":"سرعة العصر","value":"1400 دورة/دقيقة"},{"label":"عدد البرامج","value":"14 برنامج"},{"label":"تصنيف الطاقة","value":"A+++"}]',array['AI Direct Drive','دورة بخار','تحكم عبر الهاتف','قفل أمان للأطفال'],'[{"name":"أبيض","hex":"#F4F5F7"},{"name":"فضي","hex":"#B9BDC3"}]','ضمان سنتين + 10 سنوات على المحرك',true,false,true,88,55),
('heat-pump-dryer-9kg','نشافة بمضخة حرارية 9 كغم','bosch','washers','BG-WM-2002','WQB246C9GC','تجفيف لطيف بدرجات حرارة منخفضة','نشافة ألمانية بتقنية المضخة الحرارية توفر حتى 50% من الكهرباء، مع حساسات رطوبة تمنع التجفيف الزائد وتحافظ على أقمشتك.',1280000,null,4,array['/images/products/heat-pump-dryer.webp'],null,null,'horizontal','[{"label":"السعة","value":"9 كغم"},{"label":"التقنية","value":"مضخة حرارية"},{"label":"تصنيف الطاقة","value":"A++"},{"label":"الضجيج","value":"62 ديسبل"}]',array['تنظيف ذاتي للمكثف','حساسات رطوبة','برنامج الصوف'],'[{"name":"رمادي غامق","hex":"#4A4E54"}]','ضمان سنتين',false,true,false,9,4),
('inverter-split-ac-1-5','مكيف سبليت إنفرتر 1.5 طن','samsung','air-conditioners','BG-AC-3001','AR18TSHZ','تبريد سريع حتى 55 درجة مئوية','مكيف سبليت إنفرتر مصمم لحرارة الصيف العراقي، يعمل بكفاءة حتى 55°م، بتوفير طاقة يصل إلى 70% وتشغيل هادئ وفلتر مضاد للبكتيريا.',865000,950000,22,array['/images/products/split-ac.webp'],null,null,'horizontal','[{"label":"القدرة","value":"18000 وحدة (1.5 طن)"},{"label":"نوع الضاغط","value":"إنفرتر رقمي"},{"label":"غاز التبريد","value":"R410A"},{"label":"أقصى حرارة تشغيل","value":"55°م"}]',array['تبريد سريع Fast Cool','واي فاي','فلتر مضاد للبكتيريا','وضع النوم'],'[{"name":"أبيض","hex":"#F7F7F5"}]','ضمان 3 سنوات + 10 سنوات على الضاغط',true,false,true,142,70),
('tower-air-cooler-40l','مبردة هواء عمودية 40 لتر','xiaomi','heating-cooling','BG-HC-8001','AC-40T','تبريد بالماء مع ريموت ومؤقت','مبردة هواء اقتصادية بخزان 40 لتر وثلاث سرعات، مثالية للغرف والمكاتب، مع ريموت كنترول ومؤقت حتى 12 ساعة.',185000,null,30,array['/images/products/air-cooler.webp'],null,null,'horizontal','[{"label":"سعة الخزان","value":"40 لتر"},{"label":"القدرة","value":"120 واط"},{"label":"السرعات","value":"3 سرعات"}]',array['ريموت كنترول','مؤقت 12 ساعة','عجلات للتنقل'],'[{"name":"أبيض","hex":"#F2F3F5"}]','ضمان سنة',false,false,false,37,30),
('oled-tv-65','شاشة OLED ذكية 65 بوصة 4K','lg','tvs','BG-TV-4001','OLED65C3','ألوان مثالية وسواد حقيقي','شاشة OLED بدقة 4K ومعالج ذكاء اصطناعي، بسواد مطلق وتباين لا نهائي، تدعم Dolby Vision وDolby Atmos ومعدل تحديث 120 هرتز للألعاب.',2650000,2990000,6,array['/images/products/oled-tv.webp'],null,null,'horizontal','[{"label":"الحجم","value":"65 بوصة"},{"label":"الدقة","value":"4K UHD"},{"label":"معدل التحديث","value":"120 هرتز"},{"label":"نظام التشغيل","value":"webOS"}]',array['Dolby Vision','Dolby Atmos','HDMI 2.1','ريموت ماجيك'],'[{"name":"أسود","hex":"#17191C"}]','ضمان سنتين',true,false,false,21,25),
('gas-range-90cm','طباخ غاز 5 عيون 90 سم','beko','ovens','BG-OV-5001','GGR15114DX','فرن غاز واسع مع شواية','طباخ ستانلس ستيل 5 عيون بعين ثلاثية للطهي السريع، وفرن غاز بسعة 115 لتر مع مروحة توزيع حرارة وشواية وأمان قطع الغاز.',735000,820000,9,array['/images/products/gas-range.webp'],null,null,'horizontal','[{"label":"العرض","value":"90 سم"},{"label":"عدد العيون","value":"5 عيون"},{"label":"سعة الفرن","value":"115 لتر"},{"label":"الإشعال","value":"أوتوماتيكي"}]',array['عين ثلاثية','أمان قطع الغاز','مروحة توزيع حرارة'],'[{"name":"ستانلس ستيل","hex":"#B8BCC2"}]','ضمان سنتين',false,false,true,46,50),
('built-in-oven-71l','فرن كهربائي مدمج 71 لتر','bosch','ovens','BG-OV-5002','HBA5570S0','هواء ساخن ثلاثي الأبعاد','فرن ألماني مدمج بتقنية الهواء الساخن ثلاثي الأبعاد للطهي على ثلاث مستويات في آن واحد، مع تنظيف ذاتي وشاشة رقمية.',980000,null,7,array['/images/products/built-in-oven.webp'],null,null,'horizontal','[{"label":"السعة","value":"71 لتر"},{"label":"برامج الطهي","value":"10 برامج"},{"label":"أقصى حرارة","value":"300°م"}]',array['3D Hot Air','تنظيف EcoClean','باب بارد'],'[{"name":"أسود وستانلس","hex":"#2A2D31"}]','ضمان سنتين',false,true,false,11,8),
('digital-microwave-32l','مايكروويف ديجيتال 32 لتر','samsung','kitchen','BG-KT-7003','MG32K3515AS','شواية وتسخين سريع','مايكروويف بسعة 32 لتر مع شواية، وتجويف سيراميك سهل التنظيف مضاد للبكتيريا، وبرامج طهي تلقائية.',210000,245000,25,array['/images/products/microwave.webp'],null,null,'horizontal','[{"label":"السعة","value":"32 لتر"},{"label":"القدرة","value":"900 واط"},{"label":"الشواية","value":"1500 واط"}]',array['تجويف سيراميك','إذابة سريعة','قفل أطفال'],'[{"name":"ستانلس","hex":"#BFC3C8"}]','ضمان سنة',false,false,false,58,60),
('cordless-stick-vacuum','مكنسة لاسلكية عمودية','dyson','vacuums','BG-VC-6001','V15-DETECT','ليزر يكشف الغبار الدقيق','مكنسة لاسلكية بشفط قوي ورأس ليزر يكشف الغبار غير المرئي، مع حساس يحسب حجم الجزيئات وبطارية تدوم حتى 60 دقيقة.',1190000,null,10,array['/images/products/stick-vacuum.webp'],null,null,'horizontal','[{"label":"مدة البطارية","value":"حتى 60 دقيقة"},{"label":"قوة الشفط","value":"230 واط هوائي"},{"label":"سعة الحاوية","value":"0.76 لتر"},{"label":"الوزن","value":"3 كغم"}]',array['رأس ليزر','شاشة LCD','فلتر HEPA'],'[{"name":"ذهبي ونيكل","hex":"#C9A974"}]','ضمان سنتين',true,false,true,73,45),
('robot-vacuum-station','روبوت مكنسة ذكي مع محطة تفريغ','xiaomi','vacuums','BG-VC-6002','X20-PRO','ملاحة ليزر وتفريغ تلقائي','روبوت تنظيف يكنس ويمسح معاً، بملاحة ليزر LDS ترسم خريطة منزلك، ومحطة تفريغ تلقائية تكفي 60 يوماً دون تدخل.',695000,790000,12,array['/images/products/robot-vacuum.webp','/videos/robot-vacuum-poster.webp'],'/videos/robot-vacuum.mp4','/videos/robot-vacuum-poster.webp','horizontal','[{"label":"قوة الشفط","value":"5000 باسكال"},{"label":"الملاحة","value":"ليزر LDS"},{"label":"مدة البطارية","value":"180 دقيقة"},{"label":"سعة المحطة","value":"60 يوم"}]',array['كنس ومسح','تحكم بالتطبيق','تفادي العوائق','تفريغ تلقائي'],'[{"name":"أبيض","hex":"#F5F5F3"}]','ضمان سنة',true,true,false,29,10),
('espresso-machine-grinder','ماكينة إسبريسو مع مطحنة مدمجة','delonghi','kitchen','BG-KT-7001','EC9355.M','قهوة باريستا في بيتك','ماكينة إسبريسو نصف أوتوماتيكية مع مطحنة مخروطية بـ 8 درجات طحن، ومضخة 15 بار وذراع بخار لرغوة الحليب كالمقاهي.',865000,null,6,array['/images/products/espresso-machine.webp','/videos/espresso-poster.webp'],'/videos/espresso.mp4','/videos/espresso-poster.webp','vertical','[{"label":"الضغط","value":"15 بار"},{"label":"درجات الطحن","value":"8 درجات"},{"label":"خزان الماء","value":"2 لتر"},{"label":"القدرة","value":"1450 واط"}]',array['مطحنة مدمجة','ذراع بخار','مقياس ضغط'],'[{"name":"ستانلس","hex":"#C2C5C9"}]','ضمان سنتين',true,false,true,51,35),
('stand-mixer-6-7l','عجانة احترافية 6.7 لتر','kenwood','kitchen','BG-KT-7002','KVL4100','وعاء ستانلس ومحرك قوي','عجانة بمحرك 1200 واط ووعاء ستانلس 6.7 لتر، مع خطاف عجين ومضرب وخفاقة، مثالية للمعجنات والكيك.',545000,620000,11,array['/images/products/stand-mixer.webp'],null,null,'horizontal','[{"label":"سعة الوعاء","value":"6.7 لتر"},{"label":"القدرة","value":"1200 واط"},{"label":"السرعات","value":"6 سرعات + نبض"}]',array['3 ملحقات','غطاء واقٍ','قاعدة ثابتة'],'[{"name":"كحلي","hex":"#1F3A5F"},{"name":"أبيض","hex":"#F3F1EC"}]','ضمان سنتين',false,false,false,24,40),
('digital-air-fryer-6l','قلاية هوائية ديجيتال 6.2 لتر','philips','small-appliances','BG-SA-9001','HD9270','طهي صحي بدون زيت','قلاية هوائية بتقنية Rapid Air تقلي وتشوي بأقل من 90% دهون، بشاشة لمس و7 برامج جاهزة ونافذة مراقبة.',165000,195000,40,array['/images/products/air-fryer.webp'],null,null,'horizontal','[{"label":"السعة","value":"6.2 لتر"},{"label":"القدرة","value":"2000 واط"},{"label":"البرامج","value":"7 برامج"}]',array['نافذة مراقبة','قابلة للغسل بالجلاية','إيقاف تلقائي'],'[{"name":"أسود","hex":"#1C1D20"}]','ضمان سنتين',false,false,true,131,65),
('kettle-toaster-set-gold','طقم غلاية ومحمصة – ذهبي شامبين','kenwood','small-appliances','BG-SA-9002','ABBEY-GOLD','لمسة فخامة لمطبخك','طقم متناسق من غلاية بتحكم دقيق بالحرارة ومحمصة بفتحتين، بلون ذهبي شامبين يضيف دفئاً لمطبخك.',135000,null,18,array['/images/products/kettle-toaster.webp'],null,null,'horizontal','[{"label":"سعة الغلاية","value":"1 لتر"},{"label":"المحمصة","value":"فتحتان – 6 درجات"}]',array['تحكم بالحرارة','إيقاف تلقائي','درج فتات'],'[{"name":"ذهبي شامبين","hex":"#CDB48C"}]','ضمان سنة',false,true,false,15,5),
('oil-heater-11-fins','دفاية زيتية 11 ريشة','delonghi','heating-cooling','BG-HC-8002','TRRS1225','دفء آمن وصامت','دفاية زيتية بـ 11 ريشة وثلاث درجات حرارة، مع ثرموستات ونظام أمان ضد الانقلاب، مثالية لشتاء العراق.',155000,180000,0,array['/images/products/oil-heater.webp'],null,null,'horizontal','[{"label":"القدرة","value":"2500 واط"},{"label":"عدد الريش","value":"11 ريشة"},{"label":"درجات الحرارة","value":"3 درجات"}]',array['ثرموستات','حماية ضد الانقلاب','عجلات'],'[{"name":"أبيض","hex":"#F1F0EC"}]','ضمان سنتين',false,false,false,33,90)
) as v(slug,name,brand,cat,sku,model,short_d,descr,price,old_price,stock,images,video_url,video_poster,orient,specs,features,colors,warranty,featured,is_new,best,sales,age)
