('front-load-washer-9kg','مريم كاظم',5,'الغسيل نظيف والبخار رائع لملابس الأطفال.'),
('front-load-washer-9kg','حسن العبيدي',4,'جودة عالية والتعامل محترم.'),
('inverter-split-ac-1-5','مصطفى الربيعي',5,'يبرد بسرعة حتى بعز الظهر، واستهلاكه قليل.'),
