insert into public.faqs (question, answer, sort_order) values
('هل التوصيل متوفر لكل المحافظات؟','نعم، نوصل لجميع محافظات العراق خلال 1–4 أيام عمل. داخل بغداد غالباً خلال 24 ساعة.',1),
('كم رسوم التوصيل؟','رسوم التوصيل 10,000 د.ع، والتوصيل مجاني للطلبات التي تتجاوز 500,000 د.ع.',2),
('هل المنتجات أصلية وعليها ضمان؟','جميع منتجاتنا أصلية 100% ومستوردة من الوكلاء المعتمدين، مع ضمان رسمي يختلف حسب المنتج ويظهر في صفحة كل منتج.',3),
('ما طرق الدفع المتاحة؟','الدفع نقداً عند الاستلام أو التحويل البنكي. سيتم تفعيل الدفع الإلكتروني قريباً.',4),
('كيف أتتبع طلبي؟','من صفحة تتبع الطلب أدخل رقم الطلب ورقم هاتفك لمعرفة حالته لحظة بلحظة.',5),
('هل يمكنني إرجاع المنتج؟','يمكنك إرجاع أو استبدال المنتج خلال 7 أيام من الاستلام إذا كان بحالته الأصلية وفي علبته.',6);